CREATE TABLE IF NOT EXISTS users (id {PK}, email VARCHAR(190) NOT NULL UNIQUE, pass VARCHAR(255) NOT NULL){ENGINE};
CREATE TABLE IF NOT EXISTS settings (k VARCHAR(80) PRIMARY KEY, v TEXT){ENGINE};
CREATE TABLE IF NOT EXISTS services (id {PK}, name VARCHAR(190) NOT NULL, category VARCHAR(20) NOT NULL DEFAULT 'femmes', description TEXT, duration VARCHAR(60), price INT NOT NULL DEFAULT 0, active INT NOT NULL DEFAULT 1, sort INT NOT NULL DEFAULT 0){ENGINE};
CREATE TABLE IF NOT EXISTS clients (id {PK}, name VARCHAR(190) NOT NULL, phone VARCHAR(40), email VARCHAR(190), notes TEXT, created DATETIME DEFAULT CURRENT_TIMESTAMP){ENGINE};
CREATE TABLE IF NOT EXISTS appointments (id {PK}, client_id INT, service_id INT, name VARCHAR(190) NOT NULL, phone VARCHAR(40) NOT NULL, rdv_date DATE NOT NULL, rdv_time VARCHAR(5) NOT NULL, message TEXT, status VARCHAR(20) NOT NULL DEFAULT 'pending', created DATETIME DEFAULT CURRENT_TIMESTAMP){ENGINE};
CREATE TABLE IF NOT EXISTS posts (id {PK}, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL, excerpt TEXT, body TEXT, cover VARCHAR(255), video VARCHAR(255), video_url VARCHAR(255), published INT NOT NULL DEFAULT 1, created DATETIME DEFAULT CURRENT_TIMESTAMP){ENGINE};
CREATE TABLE IF NOT EXISTS media (id {PK}, type VARCHAR(10) NOT NULL DEFAULT 'image', file VARCHAR(255), video_url VARCHAR(255), caption VARCHAR(255), category VARCHAR(20) NOT NULL DEFAULT 'femmes', created DATETIME DEFAULT CURRENT_TIMESTAMP){ENGINE};
CREATE TABLE IF NOT EXISTS products (id {PK}, name VARCHAR(190) NOT NULL, description TEXT, price INT NOT NULL DEFAULT 0, image VARCHAR(255), stock INT NOT NULL DEFAULT 0, active INT NOT NULL DEFAULT 1, created DATETIME DEFAULT CURRENT_TIMESTAMP){ENGINE};
CREATE TABLE IF NOT EXISTS orders (id {PK}, name VARCHAR(190) NOT NULL, phone VARCHAR(40) NOT NULL, address TEXT, total INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'new', created DATETIME DEFAULT CURRENT_TIMESTAMP){ENGINE};
CREATE TABLE IF NOT EXISTS order_items (id {PK}, order_id INT NOT NULL, product_id INT, label VARCHAR(190) NOT NULL, qty INT NOT NULL, price INT NOT NULL){ENGINE};
CREATE TABLE IF NOT EXISTS reviews (id {PK}, name VARCHAR(190) NOT NULL, rating INT NOT NULL DEFAULT 5, body TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', created DATETIME DEFAULT CURRENT_TIMESTAMP){ENGINE};
CREATE TABLE IF NOT EXISTS invoices (id {PK}, number VARCHAR(30) NOT NULL, client_id INT, inv_date DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'unpaid', notes TEXT, total INT NOT NULL DEFAULT 0, created DATETIME DEFAULT CURRENT_TIMESTAMP){ENGINE};
CREATE TABLE IF NOT EXISTS invoice_items (id {PK}, invoice_id INT NOT NULL, label VARCHAR(255) NOT NULL, qty INT NOT NULL DEFAULT 1, price INT NOT NULL DEFAULT 0){ENGINE};
CREATE TABLE IF NOT EXISTS transactions (id {PK}, tr_date DATE NOT NULL, type VARCHAR(5) NOT NULL, label VARCHAR(255) NOT NULL, category VARCHAR(80), amount INT NOT NULL, invoice_id INT, created DATETIME DEFAULT CURRENT_TIMESTAMP){ENGINE}
